using System;using System.IO;using System.Linq;using System.Diagnostics;using System.Threading;using System.Security.Principal;using System.Security.Cryptography;using System.Runtime.InteropServices;using System.Collections.Generic;using System.Web.Script.Serialization;
internal static class ResourceComparison {
 static JavaScriptSerializer json=new JavaScriptSerializer();static string Hash(string f){using(var s=File.OpenRead(f))using(var h=SHA256.Create())return BitConverter.ToString(h.ComputeHash(s)).Replace("-","");}
 [StructLayout(LayoutKind.Sequential)]struct Io{public ulong ReadOps,WriteOps,OtherOps,ReadBytes,WriteBytes,OtherBytes;}[DllImport("kernel32.dll")]static extern bool GetProcessIoCounters(IntPtr h,out Io io);
 sealed class Sample{public string UTC;public double Cpu;public long Private;public ulong ReadBytes,WriteBytes,WriteOps;public bool IoAvailable=true;}
 static Sample Get(int[] ids){var s=new Sample{UTC=DateTime.UtcNow.ToString("o")};foreach(int id in ids)using(var p=Process.GetProcessById(id)){s.Cpu+=p.TotalProcessorTime.TotalSeconds;s.Private+=p.PrivateMemorySize64;Io io;if(GetProcessIoCounters(p.Handle,out io)){s.ReadBytes+=io.ReadBytes;s.WriteBytes+=io.WriteBytes;s.WriteOps+=io.WriteOps;}else s.IoAvailable=false;}return s;}
 static Process[] Matching(string path){return Process.GetProcessesByName("ThinkPadModesManual").Where(p=>{try{return String.Equals(p.MainModule.FileName,path,StringComparison.OrdinalIgnoreCase);}catch{return false;}}).ToArray();}
 static void WaitStopped(string path){long until=Environment.TickCount+20000;while(true){var list=Matching(path);if(list.Length==0)return;foreach(var p in list)p.Dispose();if(Environment.TickCount>until)throw new IOException("La version précédente termine encore sa restauration");Thread.Sleep(200);}}
 [STAThread]public static int Main(string[] args){if(args.Length!=4||args[0]!="--wait-qa")return 64;string output=Path.GetFullPath(args[1]);try{Directory.CreateDirectory(output);if(!new WindowsPrincipal(WindowsIdentity.GetCurrent()).IsInRole(WindowsBuiltInRole.Administrator)){try{Process.Start(new ProcessStartInfo(typeof(ResourceComparison).Assembly.Location,"--wait-qa \""+output+"\" \""+args[2]+"\" \""+args[3]+"\""){UseShellExecute=true,Verb="runas",WindowStyle=ProcessWindowStyle.Hidden});return 0;}catch(Exception e){File.WriteAllText(Path.Combine(output,"comparison-error.json"),json.Serialize(new{Error=e.Message,Stage="Elevation"}));return 1;}}
 string old=Path.GetFullPath(args[2]),modern=Path.GetFullPath(args[3]);if(Hash(old)!="4F7336FC0A44C997AEA7A5F64A0C335624C5878874C5DD461F73B2E6041796F8"||Hash(modern)!="B280D465DA59844BC776B55947C348B0D4EEBD02F6E585CC5691A32850158566")throw new IOException("Empreinte de version différente");var watch=Stopwatch.StartNew();while(!File.Exists(Path.Combine(output,"qa-complete.json"))||!File.Exists(Path.Combine(output,"crash-check.json"))){if(File.Exists(Path.Combine(output,"qa-error.json")))throw new IOException("Les contrôles de la nouvelle version ont échoué");if(watch.Elapsed.TotalMinutes>25)throw new IOException("Contrôles non terminés après25min");Thread.Sleep(1000);}Thread.Sleep(5000);if(File.Exists(@"C:\ProgramData\ThinkPadModes\Manual\cpu-lease.json"))throw new IOException("Une session CPU manuelle est active : comparaison non lancée");var current=Matching(modern).Where(p=>p.MainWindowHandle!=IntPtr.Zero).ToArray();if(current.Length!=1)throw new IOException("Fenêtre moderne non unique");using(var p=current[0]){p.Kill();p.WaitForExit();}WaitStopped(modern);
 using(var app=Process.Start(new ProcessStartInfo(old){UseShellExecute=false})){try{Thread.Sleep(4000);var ps=Matching(old);if(ps.Length!=3)throw new IOException("Ancienne version : trois processus attendus");int[] ids=ps.Select(p=>p.Id).ToArray();foreach(var p in ps)p.Dispose();var first=Get(ids);var samples=new List<Sample>{first};var timer=Stopwatch.StartNew();while(timer.Elapsed.TotalSeconds<300){Thread.Sleep((int)Math.Min(10000,Math.Max(1,(300-timer.Elapsed.TotalSeconds)*1000)));samples.Add(Get(ids));}var last=samples.Last();File.WriteAllText(Path.Combine(output,"baseline-five-minutes.json"),json.Serialize(new{UTC=DateTime.UtcNow.ToString("o"),Seconds=timer.Elapsed.TotalSeconds,Processes=3,Cores=Environment.ProcessorCount,CpuPercent=100*(last.Cpu-first.Cpu)/timer.Elapsed.TotalSeconds/Environment.ProcessorCount,PrivateBytesMax=samples.Max(s=>s.Private),ReadBytesDelta=last.ReadBytes-first.ReadBytes,WriteBytesDelta=last.WriteBytes-first.WriteBytes,WriteOperationsDelta=last.WriteOps-first.WriteOps,IoAvailable=last.IoAvailable,Conditions="Ancienne version au repos, ventilation Auto, aucun burn, cadence originale0.5s",Samples=samples}));}finally{if(!app.HasExited){app.Kill();app.WaitForExit();}WaitStopped(old);Process.Start(new ProcessStartInfo(modern){UseShellExecute=false});}}
 File.WriteAllText(Path.Combine(output,"comparison-complete.json"),json.Serialize(new{UTC=DateTime.UtcNow.ToString("o"),Completed=true,ModernRestarted=true}));return 0;
 }catch(Exception e){File.WriteAllText(Path.Combine(output,"comparison-error.json"),json.Serialize(new{UTC=DateTime.UtcNow.ToString("o"),Error=e.Message}));return 1;}}
}
